from __future__ import annotations


def _theme(number, title, summary, terms, code, practice):
    glossary = "; ".join(f"{term} — {definition}" for term, definition in terms)
    return {
        "number": number,
        "day": number,
        "title": title,
        "summary": summary,
        "terms": tuple(terms),
        "lecture": (
            f"Тема «{title}» нужна не для запоминания тегов, а для понимания структуры страницы. {summary}",
            f"Главные понятия: {glossary}. Находите каждое из них в видео и в рабочем примере ниже.",
            "Браузер читает HTML сверху вниз и строит дерево элементов. Вложенность, порядок и смысл тегов влияют на доступность, поиск и дальнейшее оформление страницы.",
            "Пишите минимальную разметку, проверяйте её в браузере после небольших изменений и открывайте инструменты разработчика, чтобы видеть реальную структуру документа.",
            f"Закрепление темы: {practice} После выполнения объясните своими словами, почему выбрали именно такие элементы и атрибуты.",
        ),
        "code": code.strip(),
        "practice": practice,
        "video_file": f"videos/html-course/theme-{number:02d}.mp4",
    }


